-- Estados e municípios do Brasil (IBGE 2025).
begin;

create extension if not exists postgis with schema extensions;

create table public.states (
  code text primary key check (code ~ '^[A-Z]{2}$'),
  ibge_code smallint not null unique check (ibge_code between 11 and 53),
  slug text not null unique check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
  name text not null check (char_length(btrim(name)) between 2 and 40),
  region_code text not null check (region_code in ('N', 'NE', 'CO', 'SE', 'S')),
  region_name text not null,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.states enable row level security;

create trigger states_set_updated_at
before update on public.states
for each row execute function private.set_updated_at();

create policy states_public_read
on public.states for select
to anon, authenticated
using (is_active = true);

create policy states_admin_manage
on public.states for all
to authenticated
using ((select private.is_admin()))
with check ((select private.is_admin()));

revoke all on public.states from public, anon, authenticated;
grant select on public.states to anon, authenticated;
grant insert, update, delete on public.states to authenticated;

insert into public.states (
  code, ibge_code, slug, name, region_code, region_name
)
select
  item.code,
  item.ibge_code,
  item.slug,
  item.name,
  item.region_code,
  item.region_name
from jsonb_to_recordset($states$[{"code":"AC","ibge_code":12,"slug":"acre","name":"Acre","region_code":"N","region_name":"Norte"},{"code":"AL","ibge_code":27,"slug":"alagoas","name":"Alagoas","region_code":"NE","region_name":"Nordeste"},{"code":"AP","ibge_code":16,"slug":"amapa","name":"Amapá","region_code":"N","region_name":"Norte"},{"code":"AM","ibge_code":13,"slug":"amazonas","name":"Amazonas","region_code":"N","region_name":"Norte"},{"code":"BA","ibge_code":29,"slug":"bahia","name":"Bahia","region_code":"NE","region_name":"Nordeste"},{"code":"CE","ibge_code":23,"slug":"ceara","name":"Ceará","region_code":"NE","region_name":"Nordeste"},{"code":"DF","ibge_code":53,"slug":"distrito-federal","name":"Distrito Federal","region_code":"CO","region_name":"Centro-Oeste"},{"code":"ES","ibge_code":32,"slug":"espirito-santo","name":"Espírito Santo","region_code":"SE","region_name":"Sudeste"},{"code":"GO","ibge_code":52,"slug":"goias","name":"Goiás","region_code":"CO","region_name":"Centro-Oeste"},{"code":"MA","ibge_code":21,"slug":"maranhao","name":"Maranhão","region_code":"NE","region_name":"Nordeste"},{"code":"MT","ibge_code":51,"slug":"mato-grosso","name":"Mato Grosso","region_code":"CO","region_name":"Centro-Oeste"},{"code":"MS","ibge_code":50,"slug":"mato-grosso-do-sul","name":"Mato Grosso do Sul","region_code":"CO","region_name":"Centro-Oeste"},{"code":"MG","ibge_code":31,"slug":"minas-gerais","name":"Minas Gerais","region_code":"SE","region_name":"Sudeste"},{"code":"PA","ibge_code":15,"slug":"para","name":"Pará","region_code":"N","region_name":"Norte"},{"code":"PB","ibge_code":25,"slug":"paraiba","name":"Paraíba","region_code":"NE","region_name":"Nordeste"},{"code":"PR","ibge_code":41,"slug":"parana","name":"Paraná","region_code":"S","region_name":"Sul"},{"code":"PE","ibge_code":26,"slug":"pernambuco","name":"Pernambuco","region_code":"NE","region_name":"Nordeste"},{"code":"PI","ibge_code":22,"slug":"piaui","name":"Piauí","region_code":"NE","region_name":"Nordeste"},{"code":"RJ","ibge_code":33,"slug":"rio-de-janeiro","name":"Rio de Janeiro","region_code":"SE","region_name":"Sudeste"},{"code":"RN","ibge_code":24,"slug":"rio-grande-do-norte","name":"Rio Grande do Norte","region_code":"NE","region_name":"Nordeste"},{"code":"RS","ibge_code":43,"slug":"rio-grande-do-sul","name":"Rio Grande do Sul","region_code":"S","region_name":"Sul"},{"code":"RO","ibge_code":11,"slug":"rondonia","name":"Rondônia","region_code":"N","region_name":"Norte"},{"code":"RR","ibge_code":14,"slug":"roraima","name":"Roraima","region_code":"N","region_name":"Norte"},{"code":"SC","ibge_code":42,"slug":"santa-catarina","name":"Santa Catarina","region_code":"S","region_name":"Sul"},{"code":"SP","ibge_code":35,"slug":"sao-paulo","name":"São Paulo","region_code":"SE","region_name":"Sudeste"},{"code":"SE","ibge_code":28,"slug":"sergipe","name":"Sergipe","region_code":"NE","region_name":"Nordeste"},{"code":"TO","ibge_code":17,"slug":"tocantins","name":"Tocantins","region_code":"N","region_name":"Norte"}]$states$::jsonb) as item(
  code text,
  ibge_code smallint,
  slug text,
  name text,
  region_code text,
  region_name text
)
on conflict (code) do update set
  ibge_code = excluded.ibge_code,
  slug = excluded.slug,
  name = excluded.name,
  region_code = excluded.region_code,
  region_name = excluded.region_name,
  is_active = true;

